/**
 * Validates a raw port value coming from either the CLI (already parsed into a number) or an
 * environment variable (still a string). Returns the numeric port on success and throws with a
 * descriptive message otherwise.
 *
 * Strings must be pure integers — empty, whitespace-only, or placeholder values such as `$PORT`
 * (an env var that was never expanded) are all rejected rather than silently coerced.
 */
function validatePort(value: string | number): number {
  const isNumber = typeof value === 'number';
  const received = isNumber ? `${value}` : `"${value}"`;
  const invalid = () =>
    new Error(
      `Invalid value at port. Port must be a valid number from 1 to 65535, received ${received}.`
    );

  let numeric: number;
  if (isNumber) {
    numeric = value;
  } else {
    // Only accept strings that are exclusively digits. This rejects empty/whitespace-only strings
    // and unexpanded placeholders like "$PORT" without ever interpolating them.
    if (!/^\d+$/.test(value)) {
      throw invalid();
    }
    numeric = Number(value);
  }

  if (!Number.isInteger(numeric) || numeric < 1 || numeric > 65535) {
    throw invalid();
  }

  return numeric;
}

/**
 * Resolves the port to use, honoring the priority order for the current context.
 *
 * Outside a Claude preview, an explicit `--port` wins, then `SBCONFIG_PORT`, then `PORT`. When
 * Claude launches the preview it controls the process via `PORT`, so that takes precedence over
 * the CLI flag and `SBCONFIG_PORT`. The first provided candidate is validated; if none is provided
 * the port is left untouched.
 */
function resolvePort(cliPort: number | undefined, env: Env, claudePreview: boolean): number | undefined {
  const cli = cliPort;
  const sbconfig = env.SBCONFIG_PORT;
  const port = env.PORT;

  const order = claudePreview ? [port, cli, sbconfig] : [cli, sbconfig, port];
  const chosen = order.find((value) => value !== undefined && value !== null);

  if (chosen === undefined || chosen === null) {
    return undefined;
  }

  return validatePort(chosen);
}

